using ZCodex.Core.Models;

namespace ZCodex.App.Views;

/// <summary>
/// Une ligne d'aide : un geste / chemin de menu (colonne de gauche) et sa description
/// (colonne de droite), dans les deux langues. <see cref="Key"/> et <see cref="Desc"/>
/// résolvent la langue courante A LA LECTURE — la bascule FR/EN se fait donc en rebindant
/// la liste (cf. HelpWindow.RefreshLanguage), pas en reconstruisant les données.
/// </summary>
public sealed record HelpRow(string KeyFr, string KeyEn, string DescFr, string DescEn)
{
    public string Key => AppLanguage.IsFr ? KeyFr : KeyEn;
    public string Desc => AppLanguage.IsFr ? DescFr : DescEn;
}

/// <summary>Un bloc de l'aide : titre, note d'introduction facultative, et ses lignes.</summary>
public sealed record HelpSection(string TitleFr, string TitleEn, string NoteFr, string NoteEn, HelpRow[] Rows)
{
    public string Title => AppLanguage.IsFr ? TitleFr : TitleEn;
    public string Note => AppLanguage.IsFr ? NoteFr : NoteEn;
    public bool HasNote => Note.Length > 0;
}

/// <summary>
/// Contenu de la fenêtre d'aide : catalogue des menus, actions, raccourcis et gestes souris.
/// Une feature = UNE ligne portant ses deux langues côte à côte (pas de clés dans
/// Strings.fr|en.xaml : ici le FR et l'EN se relisent d'un coup d'oeil et ne peuvent pas
/// diverger). Ajouter une feature = ajouter un <see cref="HelpRow"/> dans la bonne section,
/// puis incrémenter <see cref="VersionFr"/>/<see cref="VersionEn"/>.
/// </summary>
public static class HelpContent
{
    // Version du CONTENU de l'aide (indépendante de la version applicative de l'À propos) :
    // à incrémenter et redater à chaque mise à jour.
    public const string VersionFr = "Aide v4 — 21/08/2026";
    public const string VersionEn = "Help v4 — 2026-08-21";

    public static string Version => AppLanguage.IsFr ? VersionFr : VersionEn;

    public static string WindowTitle => AppLanguage.IsFr
        ? "Z-Codex — Aide et raccourcis"
        : "Z-Codex — Help and shortcuts";

    public static string Title => AppLanguage.IsFr ? "Aide et raccourcis" : "Help and shortcuts";

    public static string Intro => AppLanguage.IsFr
        ? "Toutes les actions de Z-Codex, classées par zone de l'interface. Les gestes clavier et souris sont indiqués dans la colonne de gauche."
        : "Every action in Z-Codex, grouped by area of the interface. Keyboard and mouse gestures are listed in the left column.";

    // Séparateur de sous-menu (Fichier > Ouvrir...).
    private const string M = " ▸ ";

    private static HelpRow R(string keyFr, string keyEn, string descFr, string descEn)
        => new(keyFr, keyEn, descFr, descEn);

    private static HelpSection S(string titleFr, string titleEn, string noteFr, string noteEn, params HelpRow[] rows)
        => new(titleFr, titleEn, noteFr, noteEn, rows);

